import{_ as t,o as a,c as e,ai as n}from"./chunks/framework.Cg3BiOJh.js";const m=JSON.parse('{"title":"Custom instructions fallback","description":"Reduced-assurance VPP v1.5 instructions for hosts without skills, MCP, or JSON tools.","frontmatter":{"title":"Custom instructions fallback","description":"Reduced-assurance VPP v1.5 instructions for hosts without skills, MCP, or JSON tools."},"headers":[],"relativePath":"custom-instructions/index.md","filePath":"custom-instructions/index.md","lastUpdated":1786775408000}'),o={name:"custom-instructions/index.md"};function i(l,s,p,c,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<p>Use this route only when your host cannot install the VPP plugin or skill and cannot call the remote MCP or JSON API. Prose instructions cannot reliably maintain conversation-global counters, enforce state transitions, or repair wrappers.</p><p>Copy the complete block into the host&#39;s system prompt or custom instructions:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Viable Prompt Protocol v1.5 (reduced-assurance fallback):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Parse only line 1 as !&lt;tag&gt; plus optional modifiers. User tags are g,q,o,c,o_f,e,e_o. Assistant tags are limited to g,q,o,c,o_f. Reject duplicate or contradictory modifiers and invalid pipeline destinations with &lt;c&gt; recovery. Mirror ordinary tags; !&lt;e&gt; --&lt;tag&gt; starts a named/new locus, !&lt;e_o&gt; routes to &lt;o&gt;, and !&lt;o&gt; --correct --&lt;tag&gt; starts a pipeline.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Track state per conversation. Tag indexes are conversation-global and continue across loci. Cycle starts at 1; every valid user !&lt;c&gt; advances it, capped at 3. Locus escapes, immediate-output escapes, explicit pipelines, and a new command after &lt;o_f&gt; reset cycle but not tag counts. At cycle 3 add both escape choices if absent. Default locus is default; unnamed jumps are locus-2, locus-3, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Every reply must be exactly:</span></span>
<span class="line"><span>&lt;assistant_tag&gt;</span></span>
<span class="line"><span>body</span></span>
<span class="line"><span>[Version=v1.5 | Tag=&lt;tag&gt;_&lt;index&gt; | Sources=&lt;none|web&gt; | Assumptions=&lt;n&gt; | Cycle=&lt;i&gt;/3 | Locus=&lt;name&gt;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Prefer the viable-prompt-protocol skill plus https://mcp.viableprompt.org/mcp; this text cannot deterministically enforce state.</span></span></code></pre></div><p>Then begin a new conversation with a VPP command on line 1, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!&lt;g&gt;</span></span>
<span class="line"><span>Explore a robust queue design.</span></span></code></pre></div><p>For deterministic enforcement, <a href="/install/">install the plugin</a> or connect to <code>https://mcp.viableprompt.org/mcp</code>. The <a href="/spec/">v1.5 specification</a> remains the normative human-readable reference.</p>`,6)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
